import{_ as a}from"./chunks/article-manage.DLEXaiWM.js";import{_ as r,c as e,o,ag as d}from"./chunks/framework._xRlcm3f.js";const b=JSON.parse('{"title":"文章管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/article-manage.md","filePath":"guide/article-manage.md","lastUpdated":1790228279000}'),l={name:"guide/article-manage.md"};function i(s,t,n,h,c,p){return o(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="文章管理" tabindex="-1">文章管理 <a class="header-anchor" href="#文章管理" aria-label="Permalink to &quot;文章管理&quot;">​</a></h1><p>文章管理是插件的统一管理入口：集中列出、筛选和操作已发布与未发布的文档。</p><p>笔记很多时，可以用<strong>发布源笔记本</strong>限定范围，把「公开内容」与「非公开内容」隔离开。</p><p><img src="'+a+'" alt="文章管理" loading="lazy"></p><h2 id="入口" tabindex="-1">入口 <a class="header-anchor" href="#入口" aria-label="Permalink to &quot;入口&quot;">​</a></h2><p>发布面板头部的<strong>房子图标</strong>（在「设置齿轮」左侧）。</p><h2 id="列表与筛选" tabindex="-1">列表与筛选 <a class="header-anchor" href="#列表与筛选" aria-label="Permalink to &quot;列表与筛选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>筛选项</th><th>说明</th></tr></thead><tbody><tr><td>发布源笔记本</td><td>多选，只看这些笔记本里的文档；<strong>留空 = 不限制</strong></td></tr><tr><td>搜索</td><td>按关键字过滤标题与内容</td></tr><tr><td>已发布</td><td>勾选后只看已发布过的文档</td></tr><tr><td>分页</td><td>底部分页切换</td></tr></tbody></table><h2 id="每一行能做什么" tabindex="-1">每一行能做什么 <a class="header-anchor" href="#每一行能做什么" aria-label="Permalink to &quot;每一行能做什么&quot;">​</a></h2><p><strong>标题列</strong>右上角的数字，表示这篇文档已发布到几个平台。</p><p>展开一行可以看到 ID、发布时间、标签、摘要，以及<strong>已发布到的平台</strong>——点任一平台图标，就能把这篇单独发到那个平台。</p><p><strong>操作列</strong>：</p><table tabindex="0"><thead><tr><th>按钮</th><th>说明</th></tr></thead><tbody><tr><td>闪发 / 单发</td><td>进入这篇文档的发布流程</td></tr><tr><td>批发</td><td>一次发到全部「已启用且已授权」的平台</td></tr><tr><td>查看</td><td>打开已发布文章的链接</td></tr><tr><td>图床</td><td>打开图床工具</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">按钮是否出现</p><p>部分操作依赖对应插件是否安装（如 siyuan-blog、PicGo 插件）。</p></div><h2 id="发布源笔记本" tabindex="-1">发布源笔记本 <a class="header-anchor" href="#发布源笔记本" aria-label="Permalink to &quot;发布源笔记本&quot;">​</a></h2><p>这是文章管理里最需要理解的一项。</p><ul><li><strong>用途</strong>：笔记多时，避免列出所有笔记本的全部文档；同时限制<strong>只能发布</strong>选中笔记本内的文档，把公开内容与非公开内容隔开。</li><li><strong>两层作用</strong>：既过滤列表，也在发布时做校验。</li><li><strong>配置位置</strong>：设置 → 偏好设置 → 发布源笔记本。</li><li><strong>留空语义</strong>：不限制。</li></ul><div class="warning custom-block"><p class="custom-block-title">越权会被拦截</p><p>配置了发布源笔记本后，发布不在范围内的文档会被拦下并给出明确提示。挂件模式同样适用这套规则。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>从某篇文档发起发布：<a href="./quick-publish.html">快速发布</a></li><li>调整发布行为：<a href="./settings.html">发布设置</a></li></ul>',20)])])}const m=r(l,[["render",i]]);export{b as __pageData,m as default};
